actions.script:
const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
suggestion = null
const address = String(emailAddress || '').trim()
const at = address.lastIndexOf('@')
const domain = at > 0 ? address.substring(at + 1).toLowerCase().replace(/\.$/, '') : ''
if (at < 1 || /\s/.test(address) || !/^[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z][a-z0-9-]+$/.test(domain)) {
    ec.message.addValidationError(null, 'emailAddress', null, L('Enter your whole email address, like name@example.com'), null)
    return
}
const SOURCES = {provider: L('IronStone knows these settings for your provider.'),
    autoconfig: L('Your mail provider publishes these settings.'),
    ispdb: L('These settings are from the Thunderbird database of mail providers.'),
    srv: L('These settings are from the DNS records of your domain.'),
    guess: L('These are guesses from your domain: check them against your provider\'s help page for mail apps (IMAP and SMTP).'),
    failed: L('The settings could not be looked up just now, so these are guesses: check them against your provider\'s help page.')}
const result = {emailAddress: address, domain: domain, providerId: null, providerName: null, source: 'guess', sourceText: SOURCES.guess,
    storeKind: 'imap', storeSecurity: 'ssl', storeHost: 'imap.' + domain, storePort: '993', smtpHost: 'smtp.' + domain, smtpPort: '587',
    smtpSecurity: 'starttls', mailUsername: address, displayName: null, appPassword: false, unsupported: false, oauthOnly: false,
    helpText: null, helpUrl: null, helpLinkText: null, noteText: null, warningText: null}
const applyProvider = (provider, setServers) => {
    if (!provider) return
    Object.assign(result, {providerId: provider.providerId, providerName: provider.providerName, appPassword: provider.appPassword,
        unsupported: provider.unsupported, helpText: provider.helpText, helpUrl: provider.helpUrl, helpLinkText: provider.helpLinkText,
        noteText: provider.noteText})
    if (setServers && provider.imap) Object.assign(result, {storeKind: 'imap', storeSecurity: provider.imap.security, storeHost: provider.imap.host,
        storePort: String(provider.imap.port)})
    if (setServers && provider.smtp) Object.assign(result, {smtpHost: provider.smtp.host, smtpPort: String(provider.smtp.port),
        smtpSecurity: provider.smtp.security})
}
const known = ec.service.sync().name('ironstone.MailSettingsServices.get#MailProvider').parameter('emailAddress', address).call()?.provider || null
if (known) {
    applyProvider(known, true)
    result.source = 'provider'
    result.sourceText = SOURCES.provider
    if (known.unsupported) result.warningText = known.helpText
    suggestion = result
    return
}
const reserved = ['example.com', 'example.org', 'example.net', 'localhost'].includes(domain) ||
        /\.(example|test|invalid|localhost|local)$/.test(domain)
if (!reserved) {
    ec.message.pushErrors()
    try {
        const found = ec.service.sync().name('org.moqui.impl.EmailClientServices.discover#EmailServer').parameter('emailAddress', address).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        if (found && found.storeHost) {
            const protocol = String(found.storeProtocol || 'imaps')
            result.source = SOURCES[found.source] ? found.source : 'guess'
            result.sourceText = SOURCES[result.source]
            Object.assign(result, {storeKind: protocol.startsWith('pop') ? 'pop' : 'imap',
                storeSecurity: protocol === 'imaps' || protocol === 'pop3s' ? 'ssl' : 'starttls', storeHost: found.storeHost,
                storePort: String(found.storePort || (protocol === 'pop3s' ? 995 : protocol === 'pop3' ? 110 : protocol === 'imap' ? 143 : 993)),
                mailUsername: found.mailUsername || address, displayName: found.displayName || null, oauthOnly: found.oauthOnly === true})
            if (found.smtpHost) Object.assign(result, {smtpHost: found.smtpHost, smtpPort: String(found.smtpPort || 587),
                smtpSecurity: found.smtpSsl === 'Y' ? 'ssl' : (found.smtpStartTls === 'Y' ? 'starttls' : 'none')})
            // a company domain at Google or Microsoft: their help
            applyProvider(ec.service.sync().name('ironstone.MailSettingsServices.get#MailProvider').parameter('storeHost', found.storeHost).call()?.provider, false)
            if (result.oauthOnly) result.warningText = L('This provider signs mail apps in only with its own sign-in (OAuth), which IronStone does not have yet; a password will most likely be refused.')
        }
    } catch (err) {
        ec.logger.warn(`Mail server discovery for ${domain} failed, the guesses are offered: ${err && err.message ? err.message : err}`)
        result.source = 'failed'
        result.sourceText = SOURCES.failed
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
suggestion = result

const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
accountList = []
failedParts = []
mailAccountCount = 0
problemCount = 0
const nowMillis = toMillis(ec.user.nowTimestamp)
const agoText = (millis) => {
    if (millis == null) return null
    const minutes = Math.round(Math.max(0, nowMillis - millis) / 60000)
    if (minutes < 1) return L('just now')
    if (minutes < 60) return ec.resource.expand(minutes === 1 ? '1 minute ago' : '${n} minutes ago', '', {n: minutes})
    const hours = Math.round(minutes / 60)
    if (hours < 24) return ec.resource.expand(hours === 1 ? '1 hour ago' : '${n} hours ago', '', {n: hours})
    return ec.l10n.format(new Date(millis), 'MMM d, h:mm a')
}
const users = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#UserEmailAccounts').call()
if (ec.message.hasError()) return
const accounts = Array.from(users?.accountList || [])
const KIND = {EakInternal: L('Internal'), EakExternal: L('Personal'), EakShared: L('Shared'), EakHosted: L('Hosted')}
const PERMISSION = {1: L('read'), 2: L('read and send'), 3: L('manage')}
const SECURITY = (ssl, starttls) => ssl === 'Y' ? 'SSL' : (starttls === 'Y' ? 'STARTTLS' : L('no security'))
for (const account of accounts) {
    const id = account.emailAccountId
    const item = {emailAccountId: id, accountName: account.accountName || account.emailAddress || id, emailAddress: account.emailAddress ?? null,
        kindLabel: KIND[account.accountKindEnumId] || account.accountKindEnumId, isInternal: account.isInternal === true,
        isShared: account.accountKindEnumId === 'EakShared', isOwner: account.isOwner === true, canManage: account.canManage === true,
        canSend: account.canSend === true, accessText: account.isOwner ? L('yours') : ec.resource.expand('shared with you: you may ${what}', '',
            {what: PERMISSION[account.level] || ''}), unreadCount: account.unreadCount ?? null, outboxErrorCount: account.outboxErrorCount || 0,
        statusId: account.statusId || 'EasActive', statusLabel: L('Active'), statusColor: 'positive', problemText: null, lastSyncText: null,
        lastSyncError: account.lastSyncError ?? null, syncing: false, setupIncomplete: false, hasServer: !!account.emailServerId,
        canSync: false, canPause: false, canResume: false, serverText: null, memberText: null, memberCount: 0,
        folderCount: Array.from(account.folderList || []).filter((folder) => !folder.removed).length,
        filingText: account.recordFilingEnumId === 'ErfAllMatches' ? L('Files mail with known contacts on their records')
            : (account.recordFilingEnumId === 'ErfLinkedOnly' ? L('Files only the mail you link') : null)}
    if (item.isInternal) {
        Object.assign(item, {accountName: L('Internal messages'), emailAddress: null, statusLabel: L('Always on'), statusColor: 'primary',
            problemText: null, accessText: L('Messages inside IronStone and your mailboxes; not removable')})
        accountList.push(item)
        continue
    }
    mailAccountCount++
    ec.message.pushErrors()
    try {
        const row = ec.entity.find('moqui.basic.email.EmailAccount').condition('emailAccountId', id)
                .selectField('emailAccountId').selectField('syncLockedUntil').selectField('lastSyncDate').one()
        const lockedUntil = toMillis(row?.syncLockedUntil)
        const lastSync = toMillis(account.lastSyncDate ?? row?.lastSyncDate)
        item.syncing = lockedUntil != null && lockedUntil > nowMillis
        item.lastSyncText = lastSync != null ? agoText(lastSync) : null
        item.setupIncomplete = item.statusId === 'EasPaused' && lastSync == null && item.hasServer && item.canManage
        const status = item.statusId
        if (!item.hasServer) Object.assign(item, {statusLabel: L('Local only'), statusColor: 'info',
            problemText: L('No server: the mail here is kept only here and does not sync')})
        else if (item.setupIncomplete) Object.assign(item, {statusLabel: L('Setup not finished'), statusColor: 'warning',
            problemText: L('The account is not syncing until its setup is finished')})
        else if (status === 'EasPaused') Object.assign(item, {statusLabel: L('Paused'), statusColor: 'grey-7', problemText: L('Sync is paused')})
        else if (status === 'EasAuthFailed') Object.assign(item, {statusLabel: L('Sign-in failed'), statusColor: 'negative',
            problemText: L('The server refused the password; mail is not syncing until it is entered again')})
        else if (status === 'EasError') Object.assign(item, {statusLabel: L('Sync failed'), statusColor: 'negative',
            problemText: item.lastSyncError || L('The last sync failed')})
        else if (item.syncing) Object.assign(item, {statusLabel: L('Syncing'), statusColor: 'info'})
        else if (lastSync == null) Object.assign(item, {statusLabel: L('Waiting for the first sync'), statusColor: 'info'})
        if (['EasAuthFailed', 'EasError'].includes(status) || item.setupIncomplete) problemCount++
        item.canSync = item.hasServer && !['EasPaused', 'EasRemoved'].includes(status) && !item.syncing
        item.canPause = item.canManage && item.hasServer && status !== 'EasPaused'
        item.canResume = item.canManage && item.hasServer && status === 'EasPaused' && !item.setupIncomplete
        if (item.canManage && account.emailServerId) {
            const server = ec.entity.find('moqui.basic.email.EmailServer').condition('emailServerId', account.emailServerId)
                    .selectField('storeHost,storePort,storeProtocol,smtpHost,smtpPort,smtpSsl,smtpStartTls').one()
            if (server) {
                const store = server.storeHost ? (String(server.storeProtocol || 'imaps').startsWith('pop') ? 'POP' : 'IMAP') + ' ' + server.storeHost : null
                const smtp = server.smtpHost ? 'SMTP ' + server.smtpHost + ' (' + SECURITY(server.smtpSsl, server.smtpStartTls) + ')' : null
                item.serverText = [store, smtp].filter((part) => part).join(' · ') || null
            }
        }
        if (item.isShared || item.canManage) {
            const members = Array.from(ec.entity.find('moqui.basic.email.EmailAccountUser').condition('emailAccountId', id)
                    .conditionDate('fromDate', 'thruDate', null).list())
            item.memberCount = members.length
            if (members.length) {
                const names = members.slice(0, 4).map((member) => {
                    const user = ec.entity.find('moqui.security.UserAccount').condition('userId', member.userId).useCache(true).disableAuthz().one()
                    return user ? (user.userFullName || user.username) : member.userId
                })
                item.memberText = names.join(', ') + (members.length > 4 ? ' ' + ec.resource.expand('and ${n} more', '', {n: members.length - 4}) : '')
            }
        }
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        failedParts.push(id)
        ec.logger.error(`Mail account ${id} of user ${ec.user.userId}: its list details failed and are left out: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    accountList.push(item)
}

const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
found = false; account = null; server = null; options = null; memberList = []; folderList = []; provider = null
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
if (!(access?.level >= 1) || access.account?.isInternal) { ec.message.addError(ec.resource.expand('Email account ${id} not found', '', {id: emailAccountId})); return }
const listed = ec.service.sync().name('ironstone.MailSettingsServices.get#MailAccountList').call()
if (ec.message.hasError()) return
account = Array.from(listed?.accountList || []).find((item) => item.emailAccountId === emailAccountId) || null
if (account == null) { ec.message.addError(ec.resource.expand('Email account ${id} not found', '', {id: emailAccountId})); return }
found = true
const raw = access.account
account.accountKindEnumId = raw.accountKindEnumId
options = {emailAccountId: emailAccountId, accountName: raw.accountName || '', color: raw.color || '',
    syncWindowDays: raw.syncWindowDays != null ? String(raw.syncWindowDays) : '',
    syncIntervalMinutes: raw.syncIntervalMinutes != null ? String(raw.syncIntervalMinutes) : '',
    recordFilingEnumId: raw.recordFilingEnumId || (raw.accountKindEnumId === 'EakExternal' ? 'ErfLinkedOnly' : 'ErfAllMatches')}
// the folders as the rail has them, with the server's path
const users = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#UserEmailAccounts').call() || {}
const mine = Array.from(users.accountList || []).find((item) => item.emailAccountId === emailAccountId)
const KIND = {EfkInbox: L('Inbox'), EfkDrafts: L('Drafts'), EfkSent: L('Sent'), EfkArchive: L('Archive'), EfkJunk: L('Spam'), EfkTrash: L('Trash'), EfkOther: L('Folder')}
folderList = Array.from(mine?.folderList || []).filter((folder) => !folder.removed).map((folder) => ({emailFolderId: folder.emailFolderId,
    kindLabel: KIND[folder.folderKindEnumId] || L('Folder'), isSpecial: folder.folderKindEnumId !== 'EfkOther',
    folderName: folder.folderName || folder.folderPath || folder.emailFolderId,
    pathText: folder.folderPath || L('only here'), unreadCount: folder.unreadCount || 0, totalCount: folder.totalCount ?? null,
    syncText: folder.subscribed === false ? L('not synced') : L('synced')}))
if (access.level >= 3 && raw.emailServerId) {
    const row = ec.entity.find('moqui.basic.email.EmailServer').condition('emailServerId', raw.emailServerId).one()
    if (row) {
        const protocol = String(row.storeProtocol || 'imaps')
        server = {emailServerId: raw.emailServerId, ownsServer: raw.ownsEmailServer === true,
            storeKind: protocol.startsWith('pop') ? 'pop' : 'imap', storeSecurity: protocol === 'imaps' || protocol === 'pop3s' ? 'ssl' : 'starttls',
            storeHost: row.storeHost || '', storePort: row.storePort != null ? String(row.storePort) : '', smtpHost: row.smtpHost || '',
            smtpPort: row.smtpPort != null ? String(row.smtpPort) : '', smtpSecurity: row.smtpSsl === 'Y' ? 'ssl' : (row.smtpStartTls === 'Y' ? 'starttls' : 'none'),
            mailUsername: row.mailUsername || '', hasPassword: !!row.mailPassword, hasStore: !!row.storeHost}
    }
}
if (access.level >= 3 && account.isShared) {
    const PERMISSION = {EapRead: L('Read'), EapSend: L('Read and send'), EapManage: L('Manage')}
    for (const member of ec.entity.find('moqui.basic.email.EmailAccountUser').condition('emailAccountId', emailAccountId)
            .conditionDate('fromDate', 'thruDate', null).orderBy('fromDate').list()) {
        const user = ec.entity.find('moqui.security.UserAccount').condition('userId', member.userId).useCache(true).disableAuthz().one()
        memberList.push({emailAccountId: emailAccountId, userId: member.userId, name: user ? (user.userFullName || user.username) : member.userId,
            username: user?.username ?? null, permissionEnumId: member.permissionEnumId || 'EapRead',
            permissionText: PERMISSION[member.permissionEnumId] || PERMISSION.EapRead})
    }
}
provider = ec.service.sync().name('ironstone.MailSettingsServices.get#MailProvider').parameters({emailAddress: raw.emailAddress,
    storeHost: server?.storeHost || null}).call()?.provider || null

const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
created = false
const invalid = (field, text) => { ec.message.addValidationError(null, field, null, L(text), null) }
const address = String(emailAddress || '').trim()
const at = address.lastIndexOf('@')
if (at < 1 || at === address.length - 1 || /\s/.test(address)) { invalid('emailAddress', 'Enter your whole email address, like name@example.com'); return }
if (!['EakExternal', 'EakShared'].includes(accountKindEnumId)) { ec.message.addError(ec.resource.expand('Unknown account kind ${kind}', '', {kind: accountKindEnumId})); return }
let existing = null
if (emailAccountId) {
    const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').parameter('emailAccountId', emailAccountId).call()
    if (ec.message.hasError()) return
    if (!(access?.level >= 1) || access.account?.isInternal) { ec.message.addError(ec.resource.expand('Email account ${id} not found', '', {id: emailAccountId})); return }
    if (access.level < 3) { ec.message.addError(ec.resource.expand('You may not change email account ${id}', '', {id: emailAccountId})); return }
    existing = access.account
}
const password = mailPassword == null ? '' : String(mailPassword)
if (passwordOnly) {
    if (!existing) { ec.message.addError(L('Which account? The account is required')); return }
    if (!password.trim()) { invalid('mailPassword', 'Enter the password (or app password)'); return }
    ec.service.sync().name('org.moqui.impl.EmailClientServices.update#EmailAccount').parameters({emailAccountId: emailAccountId,
        mailPassword: password.trim()}).call()
    return
}
const host = (value) => String(value || '').trim().toLowerCase().replace(/\.$/, '')
const hostOk = (value) => /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*$/.test(value)
const storeName = host(storeHost), smtpName = host(smtpHost)
if (!storeName || !hostOk(storeName)) { invalid('storeHost', 'Enter the incoming server, like imap.example.com'); return }
if (!smtpName || !hostOk(smtpName)) { invalid('smtpHost', 'Enter the outgoing server, like smtp.example.com'); return }
const pop = storeKind === 'pop'
const storeSsl = storeSecurity !== 'starttls'
const portOf = (value, fallback, field) => {
    const text = String(value ?? '').trim()
    if (!text) return String(fallback)
    if (!/^\d{1,5}$/.test(text) || Number(text) < 1 || Number(text) > 65535) { invalid(field, 'A port is a number from 1 to 65535'); return null }
    return text
}
const storePortText = portOf(storePort, pop ? (storeSsl ? 995 : 110) : (storeSsl ? 993 : 143), 'storePort')
if (storePortText == null) return
const smtpPortText = portOf(smtpPort, smtpSecurity === 'ssl' ? 465 : (smtpSecurity === 'none' ? 25 : 587), 'smtpPort')
if (smtpPortText == null) return
const servers = {storeHost: storeName, storePort: storePortText, storeProtocol: pop ? (storeSsl ? 'pop3s' : 'pop3') : (storeSsl ? 'imaps' : 'imap'),
    smtpHost: smtpName, smtpPort: smtpPortText, smtpSsl: smtpSecurity === 'ssl' ? 'Y' : 'N', smtpStartTls: smtpSecurity === 'starttls' ? 'Y' : 'N',
    mailUsername: String(mailUsername || '').trim() || address}
// a setup that was not finished, now of another kind: made again
if (existing && existing.accountKindEnumId !== accountKindEnumId) {
    const unfinished = existing.statusId === 'EasPaused' && existing.lastSyncDate == null
    if (!unfinished) { ec.message.addError(L('The kind of an account in use does not change; remove it and add it again')); return }
    ec.service.sync().name('org.moqui.impl.EmailClientServices.delete#EmailAccount').parameters({emailAccountId: emailAccountId, deleteLocalCopies: true}).call()
    if (ec.message.hasError()) return
    existing = null
    emailAccountId = null
}
if (existing) {
    const changes = Object.assign({emailAccountId: emailAccountId, emailAddress: address}, servers)
    if (password.trim()) changes.mailPassword = password.trim()
    ec.service.sync().name('org.moqui.impl.EmailClientServices.update#EmailAccount').parameters(changes).call()
    if (ec.message.hasError()) return
    if (displayName != null && String(displayName).trim()) {
        // the default identity's name follows the name given
        const identity = ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailAccountId', emailAccountId).condition('isDefault', 'Y').list()
        if (identity.length && !identity[0].displayName) ec.service.sync().name('org.moqui.impl.EmailClientServices.update#EmailIdentity')
                .parameters({emailIdentityId: identity[0].emailIdentityId, displayName: String(displayName).trim()}).call()
    }
    return
}
if (!password.trim()) { invalid('mailPassword', 'Enter the password (or app password)'); return }
const made = ec.service.sync().name('org.moqui.impl.EmailClientServices.create#EmailAccount').parameters(Object.assign({
    accountKindEnumId: accountKindEnumId, emailAddress: address, accountName: address, syncWindowDays: 365,
    displayName: String(displayName || '').trim() || null, mailPassword: password.trim(), authTypeEnumId: 'EatPassword'}, servers)).call()
if (ec.message.hasError()) return
emailAccountId = made.emailAccountId
created = true
// not synced until the wizard's Finish
ec.service.sync().name('org.moqui.impl.EmailClientServices.update#EmailAccount').parameters({emailAccountId: emailAccountId, statusId: 'EasPaused'}).call()

const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
success = false; stepList = []; folderMap = []; folderCount = 0; adviceText = null; provider = null
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
if (!(access?.level >= 1) || access.account?.isInternal) { ec.message.addError(ec.resource.expand('Email account ${id} not found', '', {id: emailAccountId})); return }
if (access.level < 3) { ec.message.addError(ec.resource.expand('You may not test email account ${id}', '', {id: emailAccountId})); return }
const server = access.account.emailServerId ? ec.entity.find('moqui.basic.email.EmailServer').condition('emailServerId', access.account.emailServerId)
        .selectField('storeHost,smtpHost,smtpPort,storePort').one() : null
provider = ec.service.sync().name('ironstone.MailSettingsServices.get#MailProvider').parameters({emailAddress: access.account.emailAddress,
    storeHost: server?.storeHost || null}).call()?.provider || null
const result = ec.service.sync().name('org.moqui.impl.EmailClientServices.test#EmailAccount').parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
success = result?.success === true
const LABELS = {smtp: L('Sending mail (SMTP)'), storeLogin: L('Receiving mail: signing in'), storeList: L('Receiving mail: the folders')}
const appPassword = provider?.appPassword ? ec.resource.expand('${name} needs an app password here, not your normal password.', '', {name: provider.providerName}) + ' ' : ''
const hintFor = (step) => {
    const text = String(step.message || '')
    if (/sim session/i.test(text)) return L('The connection test is off in this session.')
    if (/not in email_allowed_hosts/i.test(text)) return L('This server may not connect to that host; ask your administrator to allow it (email_allowed_hosts).')
    if (/BasicAuthBlocked|LogonDenied|basic auth/i.test(text)) return L('Microsoft no longer takes a password for this account: it needs Microsoft sign-in, which IronStone does not have yet.')
    if (/application-specific password|app password|apppassword|web login required|\bWEBALERT\b/i.test(text))
        return appPassword || L('The provider wants an app password (made in its account security settings), not your normal password.')
    if (/IMAP (access )?(is )?disabled|enable IMAP|IMAP not enabled|not enabled for IMAP/i.test(text)) return L('Turn on IMAP access in the mail settings of your provider\'s web mail, then test again.')
    if (/auth|login|logon|credential|password|username|535|534|\bNO\b|denied|rejected/i.test(text))
        return appPassword + L('The server refused the user name or password: check them (copy the password again, and use your whole email address as the user name).')
    if (/timed? ?out|timeout/i.test(text)) return L('The server did not answer: check the host and the port. A firewall may block that port.')
    if (/refused/i.test(text)) return L('Nothing answers on that port: check the port and the security. IMAP is usually 993 with SSL, SMTP 465 with SSL or 587 with STARTTLS.')
    if (/lookup|resolve|not known|no such host|nodename|dns|getaddrinfo|no address/i.test(text)) return L('That server name was not found: check its spelling.')
    if (/certificate|tls|ssl|handshake|wrong version|protocol version|record overflow/i.test(text))
        return L('The secure connection did not work: the security may not match the port. Use SSL with 993 and 465, and STARTTLS with 143 and 587.')
    if (/closed the connection|reset|broken pipe|eof/i.test(text)) return L('The server closed the connection: check the port and the security.')
    if (/no SMTP host|has no/i.test(text)) return L('Enter the server names under Server settings.')
    return L('Check the server settings and the password, and test again.')
}
stepList = Array.from(result?.stepList || []).map((step) => ({step: step.step, label: LABELS[step.step] || step.step, ok: step.ok === true,
    icon: step.ok === true ? 'sym_o_check_circle' : 'sym_o_error', color: step.ok === true ? 'positive' : 'negative',
    message: step.message || '', hint: step.ok === true ? null : hintFor(step)}))
const KIND = {EfkInbox: L('Inbox'), EfkSent: L('Sent'), EfkDrafts: L('Drafts'), EfkJunk: L('Spam'), EfkTrash: L('Trash'), EfkArchive: L('Archive')}
