else if (stepList.filter(signInFailed).length >= 2) adviceText = L('Neither server took the password: go back to enter it again, then test again.')
else adviceText = L('Go back to fix what failed, then test again.')

const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
