    ec.service.sync().name('org.moqui.impl.EmailClientServices.update#EmailIdentity').parameters({emailIdentityId: emailIdentityId,
        emailAddress: address, displayName: String(displayName || '').trim(), replyToAddress: reply, signatureHtml: signatureHtml || '',
        signaturePlacementEnumId: placement, useForReplies: useForReplies === 'Y', isDefault: isDefault === 'Y' ? true : null}).call()
    return
}
