emailIdentityId = ec.service.sync().name('org.moqui.impl.EmailClientServices.create#EmailIdentity').parameters({emailAccountId: emailAccountId,
    emailAddress: address, displayName: String(displayName || '').trim() || null, replyToAddress: reply || null, signatureHtml: signatureHtml || null,
    signaturePlacementEnumId: placement, useForReplies: useForReplies === 'Y', isDefault: isDefault === 'Y'}).call()?.emailIdentityId ?? null

const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
accountList = []; selectedAccountId = null; reply = null; statusText = null; isActive = false; hasServer = false
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').call()
if (ec.message.hasError()) return
const fmt = (millis) => millis == null ? '' : ec.l10n.format(new Date(Number(millis)), 'yyyy-MM-dd HH:mm')
const nice = (millis) => ec.l10n.format(new Date(Number(millis)), 'EEE MMM d, h:mm a')
const states = {}
for (const account of Array.from(access?.accountList || [])) {
    if (account.isInternal || !account.canManage) continue
    let on = null
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailOutOfOffice').parameter('emailAccountId', account.emailAccountId).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        states[account.emailAccountId] = out
        on = out?.isActive === true
    } catch (err) {
        ec.logger.error(`Out of office of email account ${account.emailAccountId} not read: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    accountList.push({emailAccountId: account.emailAccountId, accountName: account.accountName || account.emailAddress, emailAddress: account.emailAddress,
        hasServer: !!account.emailServerId, isOn: on === true, stateText: on == null ? L('unknown') : (on ? L('on') : L('off'))})
}
if (!accountList.length) return
const selected = accountList.find((account) => account.emailAccountId === emailAccountId) || accountList[0]
selectedAccountId = selected.emailAccountId
hasServer = selected.hasServer
const current = states[selectedAccountId]?.outOfOffice || null
isActive = states[selectedAccountId]?.isActive === true
reply = {emailAccountId: selectedAccountId, enabled: current?.enabled ? 'Y' : 'N', fromDate: fmt(current?.fromDate), thruDate: fmt(current?.thruDate),
    subject: current?.subject || '', bodyHtml: current?.bodyHtml || '', internalBodyHtml: current?.internalBodyHtml || '',
    replyOncePerDays: String(current?.replyOncePerDays ?? 4), applyToAll: 'N'}
const now = Number(ec.user.nowTimestamp)
if (isActive) statusText = current?.thruDate ? ec.resource.expand('On now, until ${until}: people who write get your reply.', '', {until: nice(current.thruDate)})
    : L('On now: people who write get your reply until you turn it off.')
else if (current?.enabled && current.fromDate != null && Number(current.fromDate) > now) statusText = ec.resource.expand('Starts ${from}.', '', {from: nice(current.fromDate)})
else if (current?.enabled && current.thruDate != null && Number(current.thruDate) <= now) statusText = ec.resource.expand('Ended ${until}.', '', {until: nice(current.thruDate)})
else statusText = L('Off.')

const L = (text) => ec.l10n.localize(text)
storedCount = 0
failedList = []
const on = enabled === 'Y' || enabled === true || enabled === 'true'
const days = String(replyOncePerDays ?? '').trim()
if (days && !/^\d{1,3}$/.test(days)) { ec.message.addValidationError(null, 'replyOncePerDays', null, L('A number of days'), null); return }
const empty = (html) => !String(html || '').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim()
if (on && empty(bodyHtml)) { ec.message.addValidationError(null, 'bodyHtml', null, L('Write the reply people get'), null); return }
const fields = {enabled: on, fromDate: fromDate, thruDate: thruDate, subject: String(subject || '').trim() || null, bodyHtml: empty(bodyHtml) ? null : bodyHtml,
    internalBodyHtml: empty(internalBodyHtml) ? null : internalBodyHtml, replyOncePerDays: days ? Number(days) : 4}
let ids = [emailAccountId]
if (applyToAll === 'Y') {
    const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').call()
    if (ec.message.hasError()) return
    ids = Array.from(access?.accountList || []).filter((account) => !account.isInternal && account.canManage && (account.emailServerId ||
        account.emailAccountId === emailAccountId)).map((account) => account.emailAccountId)
    if (!ids.includes(emailAccountId)) ids.unshift(emailAccountId)
}
// store#EmailOutOfOffice stores the whole reply, so a date, subject or internal message cleared here is cleared
const storeOne = (id) => {
    ec.service.sync().name('org.moqui.impl.EmailClientServices.store#EmailOutOfOffice').parameters(Object.assign({emailAccountId: id}, fields)).call()
}
for (const id of ids) {
    if (id === emailAccountId) {
        storeOne(id)
        if (ec.message.hasError()) return
        storedCount++
        continue
    }
    ec.message.pushErrors()
    try {
        storeOne(id)
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        storedCount++
    } catch (err) {
        failedList.push(id)
        ec.logger.error(`Out of office of email account ${id} not stored: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}

const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
textBlockList = []
groupOptions = []
const groupNames = {}
for (const member of ec.entity.find('moqui.security.UserGroupMember').condition('userId', ec.user.userId)
        .conditionDate('fromDate', 'thruDate', null).disableAuthz().list()) {
    if (groupNames[member.userGroupId]) continue
    const group = ec.entity.find('moqui.security.UserGroup').condition('userGroupId', member.userGroupId).useCache(true).disableAuthz().one()
    groupNames[member.userGroupId] = group?.description || member.userGroupId
    groupOptions.push({key: member.userGroupId, text: groupNames[member.userGroupId]})
}
groupOptions.sort((left, right) => String(left.text).localeCompare(String(right.text)))
const found = ec.service.sync().name('org.moqui.impl.EmailClientServices.find#EmailTextBlocks').parameter('searchText', searchText || null).call()
if (ec.message.hasError()) return
const textOf = (html) => String(html || '').replace(/<br\s*\/?>/gi, ' ').replace(/<\/(p|li|h\d)>/gi, ' ').replace(/<[^>]*>/g, ' ')
        .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\s+/g, ' ').trim()
for (const block of Array.from(found?.textBlockList || [])) {
    let ownerName = null
    if (!block.isOwner && block.ownerUserId) {
        const owner = ec.entity.find('moqui.security.UserAccount').condition('userId', block.ownerUserId).useCache(true).disableAuthz().one()
        ownerName = owner ? (owner.userFullName || owner.username) : block.ownerUserId
    }
    const groupName = block.userGroupId ? (groupNames[block.userGroupId] || block.userGroupId) : null
    textBlockList.push({emailTextBlockId: block.emailTextBlockId, title: block.title || '', shortcut: block.shortcut || '', bodyHtml: block.bodyHtml || '',
        bodyText: textOf(block.bodyHtml).substring(0, 140), userGroupId: block.userGroupId || '', isOwner: block.isOwner === true,
        sharedText: groupName ? (block.isOwner ? ec.resource.expand('Shared with ${group}', '', {group: groupName})
            : ec.resource.expand('From ${owner}, shared with ${group}', '', {owner: ownerName, group: groupName})) : L('Just me'),
        shortcutText: block.shortcut ? '/' + String(block.shortcut).replace(/^\//, '') : ''})
}

const L = (text) => ec.l10n.localize(text)
const name = String(title || '').trim()
if (!name) { ec.message.addValidationError(null, 'title', null, L('Give it a name'), null); return }
const word = String(shortcut || '').trim().replace(/^\//, '')
if (word && !/^[^\s\/]{1,40}$/.test(word)) { ec.message.addValidationError(null, 'shortcut', null, L('A shortcut is one word, without spaces'), null); return }
if (emailTextBlockId) {
    ec.service.sync().name('org.moqui.impl.EmailClientServices.update#EmailTextBlock').parameters({emailTextBlockId: emailTextBlockId, title: name,
        shortcut: word, bodyHtml: bodyHtml || '', userGroupId: userGroupId || ''}).call()
    return
}
emailTextBlockId = ec.service.sync().name('org.moqui.impl.EmailClientServices.create#EmailTextBlock').parameters({title: name, shortcut: word || null,
    bodyHtml: bodyHtml || null, userGroupId: userGroupId || null}).call()?.emailTextBlockId ?? null

const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
ruleList = []; blockedList = []; accountList = []
const users = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#UserEmailAccounts').call()
if (ec.message.hasError()) return
const KIND = {EfkInbox: L('Inbox'), EfkDrafts: L('Drafts'), EfkSent: L('Sent'), EfkArchive: L('Archive'), EfkJunk: L('Spam'), EfkTrash: L('Trash')}
const folderNames = {}, labelNames = {}
for (const account of Array.from(users?.accountList || [])) {
    if (account.isInternal || !account.canSend) continue
    const folders = Array.from(account.folderList || []).filter((folder) => !folder.removed && folder.folderKindEnumId !== 'EfkDrafts')
        .map((folder) => ({value: folder.emailFolderId, label: KIND[folder.folderKindEnumId] || folder.folderName || folder.folderPath || folder.emailFolderId,
            kind: folder.folderKindEnumId}))
    for (const folder of folders) folderNames[folder.value] = folder.label
    const labels = Array.from(account.labelList || []).map((label) => ({value: label.emailLabelId, label: label.labelName || label.emailLabelId}))
    for (const label of labels) labelNames[label.value] = label.label
    accountList.push({emailAccountId: account.emailAccountId, accountName: account.accountName || account.emailAddress, emailAddress: account.emailAddress,
        canManage: account.canManage === true, folderList: folders, labelList: labels})
}
const found = ec.service.sync().name('org.moqui.impl.EmailClientServices.find#EmailRules').call()
if (ec.message.hasError()) return
const FIELD = {from: L('From'), to: L('To'), cc: L('Cc'), subject: L('Subject'), body: L('The text'), hasAttachment: L('Has a file'),
    listId: L('Mailing list'), size: L('Size'), header: L('Header')}
const OPERATOR = {contains: L('contains'), is: L('is'), matches: L('matches'), startsWith: L('starts with'), greater: L('is larger than'), less: L('is smaller than')}
const conditionText = (condition) => {
    if (condition.field === 'hasAttachment') return condition.value === 'N' ? L('No file attached') : L('Has a file attached')
    const field = condition.field === 'header' ? (condition.header || L('Header')) : (FIELD[condition.field] || condition.field)
    return field + ' ' + (OPERATOR[condition.operator] || condition.operator) + ' "' + condition.value + '"'
}
const actionText = (action) => {
    switch (action.action) {
        case 'moveToFolder': return ec.resource.expand('Move to ${folder}', '', {folder: folderNames[action.value] || action.value})
        case 'addLabel': return ec.resource.expand('Label ${label}', '', {label: labelNames[action.value] || action.value})
        case 'markRead': return L('Mark read')
        case 'flag': return L('Flag')
        case 'forwardTo': return ec.resource.expand('Forward to ${to}', '', {to: action.value})
        case 'delete': return L('Delete')
        case 'markSpam': return L('Move to Spam')
        case 'stopProcessing': return L('Stop: no more rules')
        default: return action.action
    }
}
for (const rule of Array.from(found?.ruleList || [])) {
    const conditions = Array.from(rule.conditionList || []), actions = Array.from(rule.actionList || [])
    const isBlock = conditions.length === 1 && conditions[0].field === 'from' && conditions[0].operator === 'is' &&
        actions.some((action) => action.action === 'markSpam')
    const item = {emailRuleId: rule.emailRuleId, ruleName: rule.ruleName || '', emailAccountId: rule.emailAccountId || '',
        accountName: rule.emailAccountId ? (rule.accountName || rule.emailAccountId) : L('All my accounts'), isOwner: rule.isOwner === true,
        enabled: rule.enabled === true, matchAllEnumId: rule.matchAllEnumId || 'ErmAll', stopProcessing: rule.stopProcessing === true,
        matchedCount: rule.matchedCount || 0, conditionList: conditions, actionList: actions, isBlock: isBlock,
        conditionText: conditions.map(conditionText).join(rule.matchAllEnumId === 'ErmAny' ? ' ' + L('or') + ' ' : ' ' + L('and') + ' '),
        actionText: actions.map(actionText).join(', ') + (rule.stopProcessing && !actions.some((action) => action.action === 'stopProcessing') ? ', ' + L('then stop') : '')}
    if (isBlock) blockedList.push({emailRuleId: rule.emailRuleId, emailAddress: conditions[0].value, accountName: item.accountName, matchedCount: item.matchedCount})
    else ruleList.push(item)
}

const name = String(ruleName || '').trim()
if (!name) { ec.message.addValidationError(null, 'ruleName', null, ec.l10n.localize('Give the rule a name'), null); return }
const flag = (value) => value == null || value === '' ? null : (value === 'Y' || value === true || value === 'true' ? 'Y' : 'N')
if (emailRuleId) {
    ec.service.sync().name('org.moqui.impl.EmailClientServices.update#EmailRule').parameters({emailRuleId: emailRuleId, ruleName: name,
        matchAllEnumId: matchAllEnumId, conditionsJson: conditionsJson ?? null, actionsJson: actionsJson ?? null, enabled: flag(enabled),
        stopProcessing: flag(stopProcessing)}).call()
    return
}
emailRuleId = ec.service.sync().name('org.moqui.impl.EmailClientServices.create#EmailRule').parameters({ruleName: name,
    emailAccountId: emailAccountId || null, matchAllEnumId: matchAllEnumId, conditionsJson: conditionsJson || '[]', actionsJson: actionsJson || '[]',
    enabled: flag(enabled) || 'Y', stopProcessing: flag(stopProcessing) || 'N'}).call()?.emailRuleId ?? null

const pref = (key) => ec.user.getPreference(key)
const pane = pref('MAIL_READING_PANE')
const undo = pref('MAIL_UNDO_SECONDS')
mailDefaults = {readingPane: ['right', 'bottom', 'off'].includes(pane) ? pane : 'right', archiveOpensNext: pref('MAIL_ARCHIVE_NEXT') === 'N' ? 'N' : 'Y',
    markReadSeconds: String(Number(pref('MAIL_MARK_READ_SECONDS') || 0)), undoSeconds: undo != null && undo !== '' ? String(Number(undo)) : '10',
    remoteImages: pref('MAIL_REMOTE_IMAGES') === 'always' ? 'always' : 'ask'}

const L = (text) => ec.l10n.localize(text)
if (readingPane != null) {
    if (!['right', 'bottom', 'off'].includes(readingPane)) { ec.message.addError(L('The reading pane is right, bottom or off')); return }
    ec.user.setPreference('MAIL_READING_PANE', readingPane)
}
if (archiveOpensNext != null) ec.user.setPreference('MAIL_ARCHIVE_NEXT', archiveOpensNext === 'Y' ? 'Y' : 'N')
if (markReadSeconds != null) {
