    ec.user.setPreference('MAIL_MARK_READ_SECONDS', String(markReadSeconds))
}
if (undoSeconds != null) {
    if (!['0', '5', '10', '20', '30'].includes(String(undoSeconds))) { ec.message.addError(L('Undo send is 0, 5, 10, 20 or 30 seconds')); return }
    ec.user.setPreference('MAIL_UNDO_SECONDS', String(undoSeconds))
}
if (remoteImages != null) ec.user.setPreference('MAIL_REMOTE_IMAGES', remoteImages === 'always' ? 'always' : 'ask')
